        "body": "Um contrato cria relações entre pessoas: cada parte pode assumir obrigações e adquirir direitos. Antes de estudar uma conta bancária, separe quatro perguntas: quem é a pessoa envolvida; ela pode praticar pessoalmente aquele ato; outra pessoa atua em seu nome e com quais poderes; qual domicílio é relevante à relação? Documento é um registro usado para comprovar informações, não a própria pessoa nem uma autorização ilimitada. Esta aula ensina o vocabulário civil básico. Os exemplos são fictícios, sem CPF, número de conta ou documento pessoal. A lista de documentos e as regras bancárias para abrir ou movimentar contas pertencem à unidade seguinte.",
