        "heading": "2. Pessoa física e pessoa jurídica",
        "body": "Pessoa natural, também chamada pessoa física, é o ser humano considerado nas relações jurídicas. Ter direitos e deveres não depende de já ser adulto. A personalidade civil começa com o nascimento com vida, e o Código Civil protege os direitos do nascituro desde a concepção; nascituro é quem foi concebido e ainda não nasceu. Pessoa jurídica é uma entidade à qual o direito reconhece personalidade própria, distinta das pessoas que a compõem. Nosso exemplo será uma sociedade limitada regularmente constituída e registrada. Ato constitutivo é o documento que estabelece a organização; nesse exemplo, é o contrato social. Para pessoas jurídicas de direito privado, a existência legal começa com o registro do ato constitutivo, observada eventual autorização ou aprovação exigida. A pessoa jurídica não se confunde com seus sócios ou administradores. Não conclua, apenas pelo nome de uma loja ou atividade, que existe uma pessoa jurídica separada: o caso deve informar sua constituição.",
