        "type": "worked-example",
        "heading": "3. Exemplo resolvido: a sociedade e sua administradora",
        "body": "Caso fictício: a sociedade limitada Oficina Cedro está regularmente constituída e registrada. Marina, adulta, é sua administradora. Passo 1: Marina é pessoa física; Oficina Cedro, no caso, é pessoa jurídica. Passo 2: um contrato da sociedade não passa a ser um contrato pessoal de Marina apenas porque ela o assina em nome da sociedade. Passo 3: é preciso conferir se Marina tem poderes para o ato. Os atos dos administradores obrigam a pessoa jurídica quando praticados dentro dos poderes definidos no ato constitutivo. Não basta identificar o cargo e presumir qualquer autorização. Esta distinção também não afirma que administradores ou sócios nunca possam responder pessoalmente; as hipóteses de responsabilidade não são o tema desta aula.",
