        "heading": "4. Ter direitos é diferente de exercê-los pessoalmente",
        "body": "Capacidade de direito é a aptidão para ter direitos e deveres. Capacidade de exercício trata de praticar pessoalmente os atos da vida civil. Uma criança pode ter direitos, embora não exerça sozinha os atos civis. Pelo critério etário do Código Civil, quem ainda não completou 16 anos é absolutamente incapaz de exercer pessoalmente esses atos; quem completou 16 e ainda não completou 18 é relativamente incapaz, ressalvada a emancipação. Aos 18 anos cessa a menoridade. Nos casos de filhos menores sujeitos ao poder familiar, os pais os representam antes dos 16 e os assistem, a partir dos 16 até a maioridade, nos atos em que a assistência é necessária, sem desconsiderar a emancipação. Representar é atuar em nome da pessoa. Assistir é participar do ato com ela para suprir a limitação de exercício; não é a mesma atuação substitutiva. Poder familiar é o conjunto legal de deveres e poderes dos pais em relação aos filhos menores. Ter um direito, portanto, não prova que a pessoa pode exercê-lo sozinha.",
