        "heading": "6. Idade, emancipação e deficiência: evite atalhos",
        "body": "Emancipação é a cessação antecipada da incapacidade decorrente da menoridade nas hipóteses legais. Por exemplo, com 16 anos completos, pode haver concessão pelos pais, ou por um deles na falta do outro, mediante instrumento público, independentemente de homologação judicial; a lei também prevê sentença do juiz, ouvido o tutor, nessa idade. Instrumento público é o documento formal produzido pela autoridade competente; mera permissão verbal não equivale a ele. O art. 5º também prevê hipóteses ligadas a casamento, emprego público efetivo, colação de grau em curso de ensino superior e estabelecimento civil/comercial ou emprego que proporcione economia própria ao menor com 16 anos completos, ainda antes dos 18. Nessa hipótese, receber qualquer quantia ou simplesmente ter emprego não basta para presumir todos os requisitos. Não precisará decorar essas hipóteses nesta prática: quando relevante, o caso informará emancipação válida.\n\nO critério de idade não esgota o art. 4º: há outras hipóteses de incapacidade relativa, como impossibilidade transitória ou permanente de exprimir a vontade. Isso não permite deduzir incapacidade a partir de aparência, diagnóstico ou deficiência. A Lei Brasileira de Inclusão estabelece que deficiência não afeta a plena capacidade civil. Curatela, medida de proteção quando necessária conforme a lei, é extraordinária, proporcional ao caso e limitada aos atos patrimoniais e negociais previstos; não é uma consequência automática da deficiência. Precisar de acessibilidade ou auxílio de comunicação não equivale a ser incapaz. Esta introdução não ensina a determinar curatela, nem suas formalidades.",
