        "heading": "8. De onde vêm os poderes para agir por outra pessoa?",
        "body": "Os poderes de representação podem decorrer da lei ou ser conferidos pelo interessado. A atuação dos pais no exemplo da criança tem fundamento legal. Já uma pessoa capaz pode autorizar alguém a praticar atos em seu nome por mandato. Mandante é quem confere os poderes; mandatário é quem os recebe. A procuração é o instrumento do mandato: é preciso ler o objetivo e a extensão dos poderes, além de identificar as partes. Atuar dentro desses limites produz efeitos para o representado. O representante deve demonstrar sua qualidade e seus poderes a quem trata com ele. Ser parente, portar um documento de identidade alheio ou acompanhar alguém não demonstra, por si, esses poderes.\n\nA forma da outorga deve observar a forma legalmente exigida para o ato. Uma procuração em termos gerais só confere poderes de administração; atos que ultrapassam a administração ordinária exigem poderes especiais e expressos, como alienar ou hipotecar. Não vamos classificar aqui todos os serviços bancários. A regra de leitura é comparar o ato pedido com os poderes efetivamente conferidos, sem completar o documento por suposição.",
