    "shortTitle": "PC-03",
    "kind": "lesson",
    "objective": "Distinguir funções de cartão, interpretar datas e valores da fatura e reconhecer o crédito usado, sem confundir limite com renda ou compra parcelada com financiamento do saldo.",
    "xp": 100,
