                "text": "O BCB esclarece que a instituição pode analisar e conceder ou não o empréstimo; manter uma conta não obriga a aprovação. Na leitura de propostas, não extrapole condições de uma pessoa para outra. A página de taxas do BCB apresenta médias por modalidade e período, não uma oferta garantida a todo cliente. Cadastro, entrada e garantias podem integrar diferenças nas condições observadas; a aula não ensina a determinar preço ou aprovação."
